-- Bump vendor coverage per city from 1 to 5, mirroring migration 0017 for
-- venues (see that file's comment for why the temporary _seed_marker
-- column is needed for the jitter step). Adds 4 more vendors (cycling
-- through the categories not already used) for each of the 255 cities
-- seeded in migration 0011, with coordinates copied from the same city
-- center used in 0012 and then jittered like every other vendor row (see
-- 0013). Run this once -- re-running will jitter these rows further.
alter table vendors add column if not exists _seed_marker boolean;

insert into vendors (name, category, region, state, city, price_tier, description, contact_email, latitude, longitude, _seed_marker)
