update vendors
set
  latitude = latitude + ((abs(hashtext(id::text || 'lat')) % 2000) / 1000.0 - 1.0) * 0.02,
  longitude = longitude + ((abs(hashtext(id::text || 'lng')) % 2000) / 1000.0 - 1.0) * 0.02
where _seed_marker = true;

alter table vendors drop column _seed_marker;
